sys_script_fix.script:
function forceCDSrepull() {
	var tables = ['samp_content_version', 'samp_sw_publisher', 'samp_sw_product'];
	var clientSchedule = new GlideMultipleUpdate('cds_client_schedule');
	clientSchedule.addQuery('table.table', 'IN', tables);
	clientSchedule.setValue('last_updated_on', '');
	clientSchedule.execute();
	gs.info('Paris: Software Asset Management Foundation - Set cds_client_schedule.last_updated_on to empty is complete.');
}

forceCDSrepull();
